use crate::bridge::extern_c_api as extern_api;
use data::*;

use proptest::prelude::*;

/// container for component's incoming port values
pub struct PreStateContainer {
  pub api_tempPressureActuate: bool,
  pub api_saturationActuate: bool,
}

/// setter for component's incoming port values
pub fn put_concrete_inputs_container(container: PreStateContainer)
{
  put_tempPressureActuate(container.api_tempPressureActuate);
  put_saturationActuate(container.api_saturationActuate);
}

/// setter for component's incoming port values
pub fn put_concrete_inputs(
  tempPressureActuate: bool,
  saturationActuate: bool)
{
  put_tempPressureActuate(tempPressureActuate);
  put_saturationActuate(saturationActuate);
}

/// setter for IN DataPort
pub fn put_tempPressureActuate(value: bool)
{
  *extern_api::IN_tempPressureActuate.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// setter for IN DataPort
pub fn put_saturationActuate(value: bool)
{
  *extern_api::IN_saturationActuate.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}
